export const supportedLanguages = [
  { code: 'en', label: 'EN', name: 'English' },
  { code: 'vi', label: 'VI', name: 'Tiếng Việt' },
  { code: 'ru', label: 'RU', name: 'Русский' },
];

export const translate = (lang, key) => copy[lang]?.[key] ?? copy.en[key] ?? key;

const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [lang, setLang] = useState(() => {
    try {
      const stored = localStorage.getItem('vietsound-language');
      return copy[stored] ? stored : 'en';
    } catch {
      return 'en';
    }
  });

  useEffect(() => {
    document.documentElement.lang = lang;
    try { localStorage.setItem('vietsound-language', lang); } catch { /* ignore blocked storage */ }
  }, [lang]);

  const value = useMemo(() => ({ lang, setLang, t: (key) => translate(lang, key) }), [lang]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used inside LanguageProvider');
  return context;
}
